-- TB_EVAL_CN : 3033건
INSERT INTO TB_EVAL_CN (EVAL_ID, EVAL_ITEM_ID, ADV, DISADV, EXPC) VALUES
(1, 'WORK', '요구사항을 정확히 파악해 재작업 없이 구현함', '코드 주석과 테스트 케이스를 더 꼼꼼히 남기면 좋겠음', '다음 프로젝트에서도 핵심 모듈을 맡아 주길 바람'),
(1, 'COMM', '회의에서 의견을 명확하게 전달하고 팀 분위기를 이끎', '이슈를 공유하는 시점을 조금 앞당기면 좋겠음', '팀 내 소통 창구 역할을 계속해 주길 바람'),
(2, 'WORK', '요구사항을 정확히 파악해 재작업 없이 구현함', '코드 주석과 테스트 케이스를 더 꼼꼼히 남기면 좋겠음', '후배 팀원의 코드 리뷰를 맡아 주면 좋겠음'),
(2, 'COMM', '회의에서 의견을 명확하게 전달하고 팀 분위기를 이끎', '메신저 답변이 다소 간결함', '고객 미팅에 더 적극적으로 참여하면 좋겠음'),
(3, 'WORK', '요구사항을 정확히 파악해 재작업 없이 구현함', '코드 주석과 테스트 케이스를 더 꼼꼼히 남기면 좋겠음', '설계 단계부터 참여해 경험을 넓히면 좋겠음'),
(3, 'COMM', '회의에서 의견을 명확하게 전달하고 팀 분위기를 이끎', '이슈를 공유하는 시점을 조금 앞당기면 좋겠음', '다른 직무 팀원과의 협업 경험을 더 쌓으면 좋겠음'),
(4, 'WORK', '요구사항을 정확히 파악해 재작업 없이 구현함', '문서화가 다소 미흡함', '설계 단계부터 참여해 경험을 넓히면 좋겠음'),
(4, 'COMM', '진행 상황을 정해진 시점에 보고함', '요청에 대한 응답이 늦어 업무가 지연됨', '의견을 문서로 정리해 공유하면 좋겠음'),
(5, 'WORK', '주어진 업무를 일정 내에 무난히 수행함', '산출물 검수 단계에서 결함이 반복해서 발견됨', '후배 팀원의 코드 리뷰를 맡아 주면 좋겠음'),
(5, 'COMM', '고객과 팀원의 요청에 항상 신속히 응답함', '요청에 대한 응답이 늦어 업무가 지연됨', '일일 진행 보고를 습관화해 주길 바람'),
(6, 'WORK', '어려운 기술 이슈를 스스로 분석해 해결함', '산출물 검수 단계에서 결함이 반복해서 발견됨', '다음 프로젝트에서도 핵심 모듈을 맡아 주길 바람'),
